{
  "name": "pairwise_cost_gap_loss",
  "intuition": "This loss encourages preference for pairs with lower cost_gap by applying log-sigmoid to the negative normalized cost_gap, providing a smooth and differentiable ranking margin. Using normalized cost_gap ensures scale invariance across different cost ranges, making the signal robust. Pairwise formulation aligns with RL4CO objectives of preference modeling, promoting the selection of options with minimal cost_gap.",
  "pseudocode": "score = logsigmoid(neg(ops.normalize(batch['cost_gap']))); loss = -mean(weight * score);",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost",
    "link_family": "sigmoid",
    "agg_family": "pairwise",
    "constraint_family": "cost_gap",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "normalize", "neg", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    cost_gap = batch[\"cost_gap\"]\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    normalized_gap = ops.normalize(cost_gap)\n    score = ops.logsigmoid(ops.neg(normalized_gap))\n    return ops.mean(ops.mul(weight, score))"
}

