{
  "name": "pairwise_pref_loss_v1",
  "intuition": "This loss encourages the model to prefer pairs with higher advantage and lower cost_gap, integrating signals explicitly related to the quality difference. Using logsigmoid on advantage and cost_gap creates a smooth, differentiable preference signal that complements pairwise comparisons and emphasizes preference for better options.",
  "pseudocode": "loss = mean over pairs of [logsigmoid(advantage_w - advantage_l) + logsigmoid(-cost_gap)]",
  "hyperparams": {
    "paradigm_family": "pairwise_comparative",
    "signal_family": "advantage_cost",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "preference",
    "other_hparams": "none"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\\n    advantage_w = batch['advantage_w']\\n    advantage_l = batch['advantage_l']\\n    cost_gap = batch['cost_gap']\\n    wp = batch['log_prob_w']\\n    lp = batch['log_prob_l']\\n    weight = batch['weight']\\n    # Compute pairwise preference signals\\n    pref_signal = ops.logsigmoid(ops.sub(advantage_w, advantage_l))\\n    cost_signal = ops.logsigmoid(ops.neg(cost_gap))\\n    # Combine signals with weights\\n    combined = ops.add(pref_signal, cost_signal)\\n    # Weight by pairwise weights\\n    weighted = ops.mul(combined, weight)\\n    # Return mean over pairs as scalar\\n    loss = ops.mean(weighted)\\n    return loss"
}

