{
  "name": "pairwise_preference_margin",
  "intuition": "This loss encourages the model to assign higher log probabilities to preferred options by penalizing cases where the less preferred option's log probability is too close or higher, with a margin for strict preference. Using the cost_gap and advantage signals directly relates to the preference signal, fostering clearer preference separation.",
  "pseudocode": "loss = max(0, margin + log_prob_l - log_prob_w + weight * cost_gap)",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "comparison",
    "link_family": "margin",
    "agg_family": "pairwise",
    "constraint_family": "margin_constraints",
    "other_hparams": "margin=1.0"
  },
  "operators_used": ["logsigmoid", "max", "add", "sub", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    margin = extra.get('margin', 1.0)\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch['cost_gap']\n    diff = ops.sub(log_prob_l, log_prob_w)\n    penalize = ops.maximum(ops.add(ops.add(margin, diff), ops.mul(weight, cost_gap)), 0.0)\n    loss = ops.mean(penalize)\n    return loss"
}

{
  "name": "pairwise_logsigmoid_advantage_shift",
  "intuition": "This loss introduces a shift based on the advantage gap signal to emphasize the difference in quality between pairs, aiming to improve the sensitivity of the loss to the relative performance. By combining the advantage signal with the score difference, stabilized through clamping, it encourages the model to produce logits that better reflect the true pairwise preferences. The scale and shift are tuned to balance numerical stability and the influence of advantage signals, fostering more effective training dynamics in RL4CO scenarios.",
  "pseudocode": "x = alpha * scale * (log_prob_w - log_prob_l) + 0.1 * advantage_gap; x = clamp(x, -20, 20); loss = -logsigmoid(x); return mean(loss * weight)",
