    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "scale=1.5, shift_coefficient=0.1"
  },
  "operators_used": ["logsigmoid", "clamp", "add", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "advantage_gap", "weight"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    adv_gap = batch['advantage_gap']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.5))\n    x = ops.add(ops.mul(alpha * scale, ops.sub(lpw, lpl)), ops.mul(0.1, adv_gap))\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return loss.mean()"
}

